<?php
use Illuminate\Support\Facades\DB;
$d = '2026-09-01'; $h = '2026-10-01';
echo "== Etapas de leads de septiembre\n";
foreach (DB::select("select s.code, count(*) n, round(sum(l.lead_value)) v from kl_leads l join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id where l.created_at>=? and l.created_at<? group by s.code order by n desc", [$d,$h]) as $r) echo "  {$r->code}: {$r->n} | Bs {$r->v}\n";
$r = DB::selectOne("select min(id) a, max(id) b, count(*) n from kl_leads where created_at>=? and created_at<?", [$d,$h]); echo "  ids {$r->a}–{$r->b}: {$r->n} existen de ".($r->b-$r->a+1)."\n";
echo "== Por pipeline\n"; foreach (DB::select("select p.name, count(*) n, sum(s.code='pedidos-entregados') e, round(sum(case when s.code='pedidos-entregados' then l.lead_value end)) v from kl_leads l join kl_lead_pipelines p on p.id=l.lead_pipeline_id join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id where l.created_at>=? and l.created_at<? group by p.name order by n desc", [$d,$h]) as $r) echo "  {$r->name}: {$r->n} leads, {$r->e} entregados Bs {$r->v}\n";
echo "== Por asesor (abiertos)\n"; foreach (DB::select("select u.name, count(*) n, round(sum(l.lead_value)) v from kl_leads l join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id left join kl_users u on u.id=l.user_id where l.created_at>=? and l.created_at<? and s.code in ('no-atendido','cliente-contactado','cliente-confirmado') group by u.name order by n desc", [$d,$h]) as $r) echo "  {$r->name}: {$r->n} | Bs {$r->v}\n";
echo "== Consistencia\n";
echo "  entregados sin líneas: ".DB::selectOne("select count(*) n from kl_leads l join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id where l.created_at>=? and l.created_at<? and s.code='pedidos-entregados' and not exists(select 1 from kl_lead_products lp where lp.lead_id=l.id)", [$d,$h])->n."\n";
echo "  entregados con Bs 0: ".DB::selectOne("select count(*) n from kl_leads l join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id where l.created_at>=? and l.created_at<? and s.code='pedidos-entregados' and l.lead_value=0", [$d,$h])->n."\n";
echo "  valor ≠ líneas (con líneas): ".DB::selectOne("select count(*) n from kl_leads l where l.created_at>=? and l.created_at<? and exists(select 1 from kl_lead_products lp where lp.lead_id=l.id) and abs(l.lead_value-(select sum(quantity*price) from kl_lead_products lp where lp.lead_id=l.id))>=1", [$d,$h])->n."\n";
echo "  líneas con amount ≠ qty*price: ".DB::selectOne("select count(*) n from kl_lead_products lp join kl_leads l on l.id=lp.lead_id where l.created_at>=? and l.created_at<? and abs(lp.amount-lp.quantity*lp.price)>=1", [$d,$h])->n."\n";
echo "  cerrados sin closed_at: ".DB::selectOne("select count(*) n from kl_leads l join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id where l.created_at>=? and l.created_at<? and s.code not in ('no-atendido','cliente-contactado','cliente-confirmado') and l.closed_at is null", [$d,$h])->n."\n";
echo "  abiertos con closed_at: ".DB::selectOne("select count(*) n from kl_leads l join kl_lead_pipeline_stages s on s.id=l.lead_pipeline_stage_id where l.created_at>=? and l.created_at<? and s.code in ('no-atendido','cliente-contactado','cliente-confirmado') and l.closed_at is not null", [$d,$h])->n."\n";
echo "  attr etapa ≠ columna: ".DB::selectOne("select count(*) n from kl_leads l join kl_attribute_values av on av.entity_type='leads' and av.entity_id=l.id and av.attribute_id=28 where l.created_at>=? and l.created_at<? and av.integer_value<>l.lead_pipeline_stage_id", [$d,$h])->n."\n";
echo "  pipeline ≠ ciudad del lead: ".DB::selectOne("select count(*) n from kl_leads l join kl_attribute_values av on av.entity_type='leads' and av.entity_id=l.id and av.attribute_id=69 where l.created_at>=? and l.created_at<? and av.integer_value<>l.lead_pipeline_id", [$d,$h])->n."\n";
echo "  en 'Sin ciudad': ".DB::table('leads')->where('created_at','>=',$d)->where('created_at','<',$h)->where('lead_pipeline_id',10)->count()."\n";
echo "== Contactos creados en septiembre: ".DB::table('persons')->where('created_at','>=',$d)->where('created_at','<',$h)->count()."\n";
echo "  con 0 de más (591XXXXXXXX0): ".DB::selectOne("select count(*) n from kl_persons where created_at>=? and created_at<? and json_unquote(json_extract(contact_numbers,'$[0].value')) regexp '^591[0-9]{8}0$'", [$d,$h])->n."\n";
echo "  sin teléfono: ".DB::selectOne("select count(*) n from kl_persons where created_at>=? and created_at<? and (contact_numbers is null or json_length(contact_numbers)=0)", [$d,$h])->n."\n";
$dup = DB::select("select right(regexp_replace(json_unquote(json_extract(contact_numbers,'$[0].value')),'[^0-9]',''),8) k, count(*) n, group_concat(id) ids from kl_persons group by k having n>1 and k<>'' and max(created_at)>=? and max(created_at)<?", [$d,$h]);
echo "  números repetidos (algún contacto de sep): ".count($dup)."\n"; foreach (array_slice($dup,0,40) as $x) echo "    {$x->k}: {$x->ids}\n";
echo "  contactos de sep sin ningún lead: ".DB::selectOne("select count(*) n from kl_persons p where created_at>=? and created_at<? and not exists(select 1 from kl_leads l where l.person_id=p.id)", [$d,$h])->n."\n";
echo "== Productos tocados en septiembre\n"; foreach (DB::select("select id, name, round(price) p, created_at, updated_at from kl_products where (created_at>=? and created_at<?) or (updated_at>=? and updated_at<?) order by id", [$d,$h,$d,$h]) as $p) echo "  #{$p->id} {$p->name} Bs {$p->p} | creado {$p->created_at} | act {$p->updated_at}\n";
